#include "stdlib/blas/ext/base/ndarray/dcartesian_product.h"
#include "stdlib/ndarray/ctor.h"
#include "stdlib/ndarray/dtypes.h"
#include "stdlib/ndarray/index_modes.h"
#include "stdlib/ndarray/orders.h"
#include "stdlib/ndarray/base/bytes_per_element.h"
#include <stdint.h>
#include <stdlib.h>
#include <stdio.h>

int main( void ) {
	// Create data buffers:
	const double dataX[] = { 1.0, 2.0 };
	const double dataY[] = { 3.0, 4.0, 5.0 };
	double dataOut[ 12 ];

	// Specify input and output shapes:
	int64_t shapeX[] = { 2 };
	int64_t shapeY[] = { 3 };
	int64_t shapeOut[] = { 6, 2 };

	// Specify byte strides:
	int64_t strides[] = { STDLIB_NDARRAY_FLOAT64_BYTES_PER_ELEMENT };
	int64_t stridesOut[] = {
		2 * STDLIB_NDARRAY_FLOAT64_BYTES_PER_ELEMENT,
		STDLIB_NDARRAY_FLOAT64_BYTES_PER_ELEMENT
	};

	const enum STDLIB_NDARRAY_ORDER order = STDLIB_NDARRAY_ROW_MAJOR;
	const enum STDLIB_NDARRAY_INDEX_MODE imode = STDLIB_NDARRAY_INDEX_ERROR;
	int8_t submodes[] = { STDLIB_NDARRAY_INDEX_ERROR };

	// Create input and output ndarrays:
	// cppcheck-suppress invalidPointerCast
	struct ndarray *x = stdlib_ndarray_allocate( STDLIB_NDARRAY_FLOAT64, (uint8_t *)dataX, 1, shapeX, strides, 0, order, imode, 1, submodes );

	// cppcheck-suppress invalidPointerCast
	struct ndarray *y = stdlib_ndarray_allocate( STDLIB_NDARRAY_FLOAT64, (uint8_t *)dataY, 1, shapeY, strides, 0, order, imode, 1, submodes );

	// cppcheck-suppress invalidPointerCast
	struct ndarray *out = stdlib_ndarray_allocate( STDLIB_NDARRAY_FLOAT64, (uint8_t *)dataOut, 2, shapeOut, stridesOut, 0, order, imode, 1, submodes );
	if ( x == NULL || y == NULL || out == NULL ) {
		stdlib_ndarray_free( x );
		stdlib_ndarray_free( y );
		stdlib_ndarray_free( out );
		fprintf( stderr, "Error allocating memory.\n" );
		exit( 1 );
	}

	const struct ndarray *arrays[] = { x, y, out };
	stdlib_blas_ext_dcartesian_product( arrays );

	// Print the resulting pairs:
	for ( int i = 0; i < 6; i++ ) {
		printf( "out[ %i ] = ( %lf, %lf )\n", i, dataOut[ i*2 ], dataOut[ (i*2)+1 ] );
	}
	stdlib_ndarray_free( x );
	stdlib_ndarray_free( y );
	stdlib_ndarray_free( out );
}
